package com.ktb.hackathon.team11.attempt;import com.ktb.hackathon.team11.assignment.AssignmentStatus;import com.ktb.hackathon.team11.global.response.ApiResponse;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;
@RestController @RequestMapping("/api/v1") @RequiredArgsConstructor public class TaskAttemptController{private final TaskAttemptService service;@PostMapping(value="/assignments/{id}/photo-attempts",consumes="multipart/form-data")ApiResponse<Response> submit(@PathVariable long id,@RequestParam long workerId,@RequestPart MultipartFile photo){return ApiResponse.of("PHOTO_CHECKED",Response.from(service.submit(id,workerId,photo)));}@GetMapping("/assignments/{id}/attempts")ApiResponse<List<Response>> history(@PathVariable long id,@RequestParam long memberId){return ApiResponse.of("ATTEMPTS_FOUND",service.history(id,memberId).stream().map(Response::from).toList());}@PostMapping("/attempts/{id}/retry")ApiResponse<Response> retry(@PathVariable long id,@RequestParam long managerId){return ApiResponse.of("ATTEMPT_RETRIED",Response.from(service.retry(id,managerId)));}public record Response(Long attemptId,int attemptNumber,AttemptStatus status,AssignmentStatus assignmentStatus,String reason,String fix){static Response from(TaskAttempt a){return new Response(a.getId(),a.getAttemptNumber(),a.getStatus(),a.getAssignment().getStatus(),a.getReason(),a.getFixMessage());}}}
